import React from "react";
import HistoryTableRow from "./HistoryTableRowComponent";
import Loader from "./LoaderComponent";
import "./../css/profie.css";
import { Link } from "react-router-dom";

const API_URL = "https://iranaserviceapp.ir/test/api";
const IMAGE_URL = "https://iranaserviceapp.ir/test/files/user";

const PERSIAN_DIGITS = [
  "۰",
  "۱",
  "۲",
  "۳",
  "۴",
  "۵",
  "۶",
  "۷",
  "۸",
  "۹",
];

function toPersianDigits(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value).replace(
    /\d/g,
    (d) => PERSIAN_DIGITS[Number(d)]
  );
}

function convertDateToPersian(dateString) {
  if (!dateString) {
    return "";
  }

  try {
    const parts = String(dateString).split("/");

    if (parts.length !== 3) {
      return dateString;
    }

    const year = Number(parts[0]);
    const month = Number(parts[1]);
    const day = Number(parts[2]);

    /*
     * اگر تاریخ از قبل شمسی باشد
     * مثلا 1405/05/28
     */
    if (year < 1700) {
      return `${toPersianDigits(year)}/${toPersianDigits(
        String(month).padStart(2, "0")
      )}/${toPersianDigits(
        String(day).padStart(2, "0")
      )}`;
    }

    /*
     * تاریخ API میلادی است
     * مثلا 2026/09/06
     */
    const date = new Date(
      year,
      month - 1,
      day
    );

    const formatter = new Intl.DateTimeFormat(
      "fa-IR-u-ca-persian",
      {
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
      }
    );

    return formatter.format(date);
  } catch (error) {
    console.error(
      "DATE CONVERT ERROR:",
      error
    );

    return dateString;
  }
}

function getMonthLabel(dateString) {
  if (!dateString) {
    return "";
  }

  try {
    const parts = String(dateString).split("/");

    if (parts.length !== 3) {
      return "";
    }

    const year = Number(parts[0]);
    const month = Number(parts[1]);
    const day = Number(parts[2]);

    let date;

    /*
     * اگر تاریخ میلادی باشد
     */
    if (year >= 1700) {
      date = new Date(
        year,
        month - 1,
        day
      );
    } else {
      /*
       * اگر از قبل شمسی باشد
       */
      const converted = convertPersianToGregorian(
        year,
        month,
        day
      );

      if (!converted) {
        return "";
      }

      date = converted;
    }

    const formatter = new Intl.DateTimeFormat(
      "fa-IR-u-ca-persian",
      {
        year: "numeric",
        month: "long",
      }
    );

    return formatter.format(date);
  } catch (error) {
    console.error(
      "MONTH LABEL ERROR:",
      error
    );

    return "";
  }
}

/*
 * تبدیل تاریخ شمسی به میلادی
 * فقط برای حالتی که API تاریخ شمسی ارسال کند.
 */
function convertPersianToGregorian(
  jy,
  jm,
  jd
) {
  try {
    let gy;

    if (jy > 979) {
      gy = 1600;
      jy -= 979;
    } else {
      gy = 621;
    }

    let days =
      365 * jy +
      Math.floor(jy / 33) * 8 +
      Math.floor(((jy % 33) + 3) / 4) +
      78 +
      jd +
      (jm < 7
        ? (jm - 1) * 31
        : (jm - 7) * 30 + 186);

    gy +=
      400 *
      Math.floor(days / 146097);

    days %= 146097;

    if (days > 36524) {
      gy +=
        100 *
        Math.floor(--days / 36524);

      days %= 36524;

      if (days >= 365) {
        days++;
      }
    }

    gy +=
      4 *
      Math.floor(days / 1461);

    days %= 1461;

    if (days > 365) {
      gy +=
        Math.floor((days - 1) / 365);

      days =
        (days - 1) % 365;
    }

    let gd = days + 1;

    const leap =
      (gy % 4 === 0 &&
        gy % 100 !== 0) ||
      gy % 400 === 0;

    const monthDays = [
      0,
      31,
      leap ? 29 : 28,
      31,
      30,
      31,
      30,
      31,
      31,
      30,
      31,
      30,
      31,
    ];

    let gm = 1;

    while (
      gm <= 12 &&
      gd > monthDays[gm]
    ) {
      gd -= monthDays[gm];
      gm++;
    }

    return new Date(
      gy,
      gm - 1,
      gd
    );
  } catch (error) {
    return null;
  }
}

function getStatus(record) {
  /*
   * وضعیت درخواست را از اطلاعات API مشخص می‌کنیم.
   *
   * فعلاً:
   * status = 1 و end = 2 => موفق
   *
   * سایر حالت‌ها => لغو شده
   */

  if (
    Number(record.status) === 1 &&
    Number(record.end) === 2
  ) {
    return "success";
  }

  return "canceled";
}

class TechnicianProfilePage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      profile: null,
      stats: {
        settled: 0,
        canceledByTechnician: 0,
        reactivated: 0,
      },
      history: [],

      loading: true,
      error: "",
    };
  }

  componentDidMount() {
    this.getUserHistory();
  }

  // =====================================================
  // دریافت ID از آدرس
  // /user-history?id=63
  // =====================================================

  getUserId() {
    const params = new URLSearchParams(
      window.location.search
    );

    return params.get("id");
  }

  // =====================================================
  // دریافت سوابق تعمیرکار
  // =====================================================

  getUserHistory = () => {
    const userId = this.getUserId();

    if (!userId) {
      this.setState({
        loading: false,
        error: "شناسه تعمیرکار پیدا نشد.",
      });

      return;
    }

    const token =
      localStorage.getItem("token");

    this.setState({
      loading: true,
      error: "",
    });

    fetch(
      `${API_URL}/user-history?id=${encodeURIComponent(
        userId
      )}`,
      {
        method: "GET",

        headers: {
          Accept: "application/json",
          Authorization: `Bearer ${token}`,
        },
      }
    )
      .then((response) => {
        if (!response.ok) {
          throw new Error(
            `HTTP ERROR ${response.status}`
          );
        }

        return response.json();
      })
      .then((data) => {
        console.log(
          "USER HISTORY API:",
          data
        );

        if (String(data.status) !== "1") {
          this.setState({
            profile: null,
            stats: {
              settled: 0,
              canceledByTechnician: 0,
              reactivated: 0,
            },
            history: [],
            loading: false,
            error:
              data.message ||
              "اطلاعاتی پیدا نشد.",
          });

          return;
        }

        const requests =
          Array.isArray(data.requests)
            ? data.requests
            : [];

        const repairman =
          requests.length > 0 &&
          requests[0].repairman_model
            ? requests[0].repairman_model
            : null;

        // =================================================
        // پروفایل تعمیرکار
        // =================================================

        let avatar =
          "https://ui-avatars.com/api/?name=کاربر&background=e9ecef&color=495057";

        if (repairman) {
          const fullName =
            `${repairman.name || ""} ${
              repairman.family || ""
            }`.trim();

          if (repairman.image) {
            avatar =
              `${IMAGE_URL}${repairman.image}`;
          } else {
            avatar =
              `https://ui-avatars.com/api/?name=${encodeURIComponent(
                fullName || "کاربر"
              )}&background=e9ecef&color=495057`;
          }
        }

        const profile = repairman
          ? {
              name:
                `${repairman.name || ""} ${
                  repairman.family || ""
                }`.trim() ||
                "بدون نام",

              confirmedRequests:
                requests.length,

              avatar: avatar,

              id: repairman.id,
            }
          : {
              name: "بدون نام",
              confirmedRequests:
                requests.length,
              avatar: avatar,
              id: userId,
            };

        // =================================================
        // تبدیل درخواست‌ها به history
        // =================================================

        const history =
          requests.map((request) => ({
            id: request.id,

            deviceType:
              request.device_type ||
              "نامشخص",

            issue:
              request.problem ||
              "بدون توضیحات",

            date:
              convertDateToPersian(
                request.time
              ),

            status:
              getStatus(request),

            originalData: request,
          }));

        // =================================================
        // آمار
        // =================================================

        const settled =
          requests.filter(
            (request) =>
              Number(request.status) === 1 &&
              Number(request.end) === 2
          ).length;

        const canceledByTechnician =
          requests.filter(
            (request) =>
              Number(request.status) !== 1
          ).length;

        const reactivated =
          requests.filter(
            (request) =>
              Number(request.cleared) === 1
          ).length;

        this.setState({
          profile: profile,

          stats: {
            settled:
              settled,

            canceledByTechnician:
              canceledByTechnician,

            reactivated:
              reactivated,
          },

          history: history,

          loading: false,
          error: "",
        });
      })
      .catch((error) => {
        console.error(
          "USER HISTORY ERROR:",
          error
        );

        this.setState({
          profile: null,
          history: [],
          loading: false,
          error:
            "خطا در دریافت اطلاعات تعمیرکار.",
        });
      });
  };

  // =====================================================
  // Render
  // =====================================================

  render() {
    const {
      profile,
      stats,
      history,
      loading,
      error,
    } = this.state;

    // =====================================================
    // لودر
    // =====================================================

    if (loading) {
      return <Loader />;
    }

    // =====================================================
    // خطا
    // =====================================================

    if (error) {
      return (
        <div
          dir="rtl"
          className="container px-3 py-5"
        >
          <div className="text-center text-danger">
            {error}
          </div>
        </div>
      );
    }

    // =====================================================
    // اطلاعاتی وجود ندارد
    // =====================================================

    if (!profile) {
      return (
        <div
          dir="rtl"
          className="container px-3 py-5"
        >
          <div className="text-center text-muted">
            اطلاعات تعمیرکار پیدا نشد.
          </div>
        </div>
      );
    }

    let lastMonthLabel = null;

    return (
      <div dir="rtl">
        <div className="container px-3 pt-4 pb-5">

          {/* =================================================
              کارت پروفایل
          ================================================= */}

          <div className="d-flex align-items-center justify-content-between border rounded-4 p-3 mb-4">

            <div className="d-flex align-items-center gap-3 w-100">

              <img
                src={profile.avatar}
                alt={profile.name}
                width="56"
                height="56"
                className="rounded-circle"
                style={{
                  objectFit: "cover",
                }}
              />

              <div>
                <div className="fw-semibold text-dark">
                  {profile.name}
                </div>

                <div className="text-muted small">
                  {toPersianDigits(
                    profile.confirmedRequests
                  )}{" "}
                  درخواست تایید شده
                </div>
              </div>

              {/* ================= دکمه‌ها ================= */}

              <div className="d-flex flex-column gap-2 me-auto">

                <Link
                  to={`/PersonalInfoPage?id=${profile.id}`}
                  className="btn btn-primary rounded-pill btn-sm px-4 py-2"
                >
                  پروفایل
                </Link>

                <button
                  type="button"
                  className="btn btn-outline-primary rounded-pill btn-sm px-4 py-2"
                >
                  گفتگو
                </button>

              </div>
            </div>
          </div>

          {/* =================================================
              آمار
          ================================================= */}

          <h2 className="text-center fs-6 fw-semibold text-dark mb-3">
            آمار
          </h2>

          <div className="border rounded-4 p-3 mb-4 d-flex flex-column gap-3">

            {/* تسویه شده */}

            <div className="d-flex align-items-center justify-content-between">

              <span className="text-muted">
                تسویه شده
              </span>

              <span
                className="fw-semibold"
                style={{
                  color: "#5b9bf0",
                }}
              >
                {toPersianDigits(
                  stats.settled
                )}
              </span>

            </div>

            {/* کنسل شده */}

            <div className="d-flex align-items-center justify-content-between">

              <span className="text-muted">
                کنسل شده توسط تعمیرکار
              </span>

              <span className="fw-semibold text-danger">
                {toPersianDigits(
                  stats.canceledByTechnician
                )}
              </span>

            </div>

            {/* مجدد فعال */}

            <div className="d-flex align-items-center justify-content-between">

              <span className="text-muted">
                مجدد فعال‌سازی شده
              </span>

              <span className="fw-semibold text-dark">
                {toPersianDigits(
                  stats.reactivated
                )}
              </span>

            </div>

          </div>

          {/* =================================================
              سوابق
          ================================================= */}

          <h2 className="text-center fs-6 fw-semibold text-dark mb-3">
            سوابق
          </h2>

          <div className="border rounded-4 overflow-hidden">

            {/* ================= سرستون ================= */}

            <div
              style={{
                display: "grid",
                gridTemplateColumns:
                  "1fr 1.3fr 1fr 0.8fr",
                alignItems: "center",
              }}
              className="py-3 border-bottom table-header"
            >
              <span className="text-center small">
                نوع دستگاه
              </span>

              <span className="text-center small">
                ایراد دستگاه
              </span>

              <span className="text-center small">
                زمان مراجعه
              </span>

              <span className="text-center small">
                جزئیات
              </span>
            </div>

            {/* ================= اطلاعات ================= */}

            {history.length === 0 ? (
              <div className="text-center text-muted py-5">
                سابقه‌ای برای این تعمیرکار وجود ندارد.
              </div>
            ) : (
              history.map((record) => {
                const monthLabel =
                  getMonthLabel(
                    record.originalData.time
                  );

                const showMonthSeparator =
                  monthLabel !==
                  lastMonthLabel;

                lastMonthLabel =
                  monthLabel;

                return (
                  <React.Fragment
                    key={record.id}
                  >

                    {showMonthSeparator &&
                      monthLabel && (
                        <div className="text-center small text-muted py-2 bg-light border-bottom">
                          {monthLabel}
                        </div>
                      )}

                    <Link
                      to={`/request-details/${record.id}`}
                      className="text-decoration-none text-dark d-block"
                    >
                      <HistoryTableRow
                        record={record}
                      />
                    </Link>

                  </React.Fragment>
                );
              })
            )}

          </div>

        </div>
      </div>
    );
  }
}

export default TechnicianProfilePage;
